data.default.conf:
server {
    listen 80;
    server_name _;
    root /usr/share/nginx/html;

    location /blog {
        if ($host = learn.padho.ai) {
            return 308 https://padho.ai$request_uri;
        }
        if ($host = ips.padho.ai) {
            return 308 https://padho.ai$request_uri;
        }
        try_files $uri $uri/ $uri/index.html =404;
    }

    location = /healthz {
        return 200 'ok';
        add_header Content-Type text/plain;
    }

    error_page 404 /blog/404.html;
}
